 const [screen,setScreen]=useState<'landing'|'login'|'signup'|'app'>(()=>profile?'app':'landing');
 const [sidebar,setSidebar]=useState(false),[taskQuery,setTaskQuery]=useState('');
 const [chatOpen,setChatOpen]=useState(false);
 const chatPanel=useRef<HTMLElement>(null),chatButton=useRef<HTMLButtonElement>(null),chatEnd=useRef<HTMLDivElement>(null);
