 const accountPanel=useRef<HTMLElement>(null),accountButton=useRef<HTMLButtonElement>(null);
 const [modal,setModal]=useState<string|null>(null),[fileId,setFileId]=useState<string|null>(null),[history,setHistory]=useState<{taskId:string;round:Round}|null>(null);
 const [toast,setToast]=useState(''),[newName,setNewName]=useState('');
 const [authName,setAuthName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState('');
 const [playing,setPlaying]=useState(false);
 const [feedback,setFeedback]=useState<Feedback|null>(null),[note,setNote]=useState('');
 const [progress,setProgress]=useState({progress:0,message:'Preparing context'}),[chatInput,setChatInput]=useState('');
 const [messages,setMessages]=useState<ChatMessage[]>([]);
 const [diagnosis,setDiagnosis]=useState<JobView|null>(null),[chatJob,setChatJob]=useState<JobView|null>(null);
 const [viewStage,setViewStage]=useState<Stage|null>(null);
 const [models,setModels]=useState<Record<ProviderId,string>>(()=>({codex:preferredModel('codex'),claude:preferredModel('claude')}));
 const provider=status?.provider??'codex',agentName=PROVIDER_LABELS[provider],agentStatus=status?.agent,model=models[provider];
 const setModel=(value:string)=>setModels(current=>({...current,[provider]:value}));
 const [claudeKey,setClaudeKey]=useState(''),[providerBusy,setProviderBusy]=useState(false);
 const [authUrl,setAuthUrl]=useState(''),[connecting,setConnecting]=useState(false);
 const [projectPath,setProjectPath]=useState(''),[scan,setScan]=useState<ProjectScan|null>(null),[selectedPaths,setSelectedPaths]=useState<string[]>([]),[projectBusy,setProjectBusy]=useState(false);
 const jsonImport=useRef<HTMLInputElement>(null),recoveredJobs=useRef(new Set<string>()),activeTaskRef=useRef(workspace.activeTaskId);
 const applyKey=useRef<{suggestionId:string;key:string}|null>(null);
 activeTaskRef.current=workspace.activeTaskId;
 const operation=useRef<AbortController|null>(null),runTimer=useRef<ReturnType<typeof setTimeout>|null>(null),upload=useRef<HTMLInputElement>(null);
 const task=getActiveTask(workspace),round=getActiveRound(workspace),stage=viewStage??(diagnosis?.taskId===workspace.activeTaskId&&diagnosis.status==='running'?'investigating':workspace.stage),obs=round.observation,suggestion=round.suggestion;
 const waiting=stage==='investigating'||stage==='applying';
 const selectedFile=task.files.find(f=>f.id===fileId)||task.files[0];
 useEffect(()=>{if(mode==='local'){setScreen('app');setProfile({name:'Local maker',email:status?.agent.account?.email||'This computer'})}},[mode,status?.agent.account?.email]);
 useEffect(()=>{try{for(const id of Object.keys(models) as ProviderId[])window.localStorage.setItem(modelKey(id),models[id])}catch{}},[models]);
 useEffect(()=>{if(!authUrl||mode!=='local')return;const timer=setInterval(()=>{void refreshStatus().then(value=>{if(value.provider!=='codex')setAuthUrl('');else if(value.agent.authenticated){setAuthUrl('');notify('Codex connected. Choose a model or start diagnosing.')}}).catch(()=>{})},3000);return()=>clearInterval(timer)},[authUrl,mode,refreshStatus]);
 useEffect(()=>{if(mode!=='local')return;let alive=true;setMessages([]);void localApi<ChatMessage[]>(`/api/tasks/${encodeURIComponent(task.id)}/messages`).then(value=>{if(alive)setMessages(value)}).catch(e=>{if(alive)setError((e as Error).message)});return()=>{alive=false}},[mode,task.id,setError]);
 useEffect(()=>{if(mode!=='local')return;for(const job of initialJobs){if(job.taskId!==task.id||recoveredJobs.current.has(job.id))continue;recoveredJobs.current.add(job.id);if(job.kind==='investigate')setDiagnosis(job);else setChatJob(job)}},[initialJobs,mode,task.id]);
 useEffect(()=>{
  if(!diagnosis?.id||mode!=='local')return;
  const ctl=new AbortController(),jobId=diagnosis.id;
  void followJob(jobId,job=>{setDiagnosis(job);setProgress({progress:job.status==='completed'?100:35,message:job.message||`${PROVIDER_LABELS[job.provider??'codex']} is reading the selected context…`})},ctl.signal).then(async job=>{await reload();if(job.status!=='completed')setError(job.error||`${PROVIDER_LABELS[job.provider??'codex']} task ${job.status}. You can retry with your context intact.`);setDiagnosis(null)}).catch(e=>{if(!ctl.signal.aborted){setError(`${(e as Error).message} The job remains on the server; reload to recover it.`);setDiagnosis(null)}});
  return()=>ctl.abort();
 },[diagnosis?.id,mode,reload,setError]);
 useEffect(()=>{
  if(!chatJob?.id||mode!=='local')return;
  const ctl=new AbortController(),jobId=chatJob.id,targetId=chatJob.taskId;
  void followJob(jobId,setChatJob,ctl.signal).then(async job=>{const saved=await localApi<ChatMessage[]>(`/api/tasks/${encodeURIComponent(targetId)}/messages`);if(activeTaskRef.current===targetId)setMessages(saved);if(job.status!=='completed')setError(job.error||`Chat ${job.status}.`);setChatJob(null)}).catch(e=>{if(!ctl.signal.aborted){setError((e as Error).message);setChatJob(null)}});
  return()=>ctl.abort();
 },[chatJob?.id,mode,setError]);
 useEffect(()=>{setFeedback(null);setNote('')},[workspace.activeTaskId,task.activeRoundId]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(timer)},[toast]);
 useEffect(()=>()=>{operation.current?.abort();if(runTimer.current)clearTimeout(runTimer.current)},[]);
 useEffect(()=>{setPlaying(false);if(runTimer.current)clearTimeout(runTimer.current);window.scrollTo({top:0,behavior:'instant'})},[stage,screen]);
 useEffect(()=>{const listener=(e:KeyboardEvent)=>{if(e.key==='Escape'){setSidebar(false);if(chatOpen){setChatOpen(false);chatButton.current?.focus()}if(accountOpen){setAccountOpen(false);accountButton.current?.focus()}}if(screen!=='app'||stage!=='observe'||modal||sidebar||/INPUT|TEXTAREA|SELECT/.test((e.target as HTMLElement).tagName)||(e.target as HTMLElement).isContentEditable||e.repeat||e.metaKey||e.ctrlKey||e.altKey)return;const n=Number(e.key);if(n>=1&&n<=6)chooseIssue(ISSUES[n-1])};document.addEventListener('keydown',listener);return()=>document.removeEventListener('keydown',listener)},[screen,stage,modal,sidebar,chatOpen,accountOpen]);
 useEffect(()=>{
  if(!accountOpen)return;
  const position=()=>{const rect=accountButton.current?.getBoundingClientRect();if(!rect)return;if(rect.bottom<0){setAccountOpen(false);return}setAccountPosition({top:rect.bottom+12,right:Math.max(16,window.innerWidth-rect.right)})};
  const outside=(event:PointerEvent)=>{const target=event.target as Node;if(!accountPanel.current?.contains(target)&&!accountButton.current?.contains(target))setAccountOpen(false)};
  position();accountPanel.current?.focus();window.addEventListener('resize',position);window.addEventListener('scroll',position,true);document.addEventListener('pointerdown',outside);
  return()=>{window.removeEventListener('resize',position);window.removeEventListener('scroll',position,true);document.removeEventListener('pointerdown',outside)};
 },[accountOpen]);
 useEffect(()=>{if(modal||sidebar||screen!=='app')setAccountOpen(false)},[modal,sidebar,screen]);
 useEffect(()=>{if(chatOpen)chatPanel.current?.querySelector<HTMLInputElement>('input')?.focus()},[chatOpen]);
 useEffect(()=>{if(chatOpen)chatEnd.current?.scrollIntoView({block:'nearest'})},[messages,chatOpen]);
 function chooseIssue(issue:Issue){setWorkspace(s=>toggleIssue(s,issue))}
 function patchObs(patch:Partial<Observation>){setWorkspace(s=>reviseObservation(s,patch))}
 function go(next:Stage){if(mode==='local'&&viewStage==='applying')return;operation.current?.abort();if(mode==='local'&&diagnosis?.status==='running'){void cancelDiagnosis(next);return}if(next==='setup'&&task.hardware.configured&&stage!=='setup'){setSidebar(true);notify('Hardware setup opens when you switch or create a task.');return}if(round.applied&&['observe','request','investigating'].includes(next))notify('Record the result of this change before starting another observation.');setWorkspace(s=>setStage(s,next))}
 function notify(text:string){setToast(text)}
 function openFiles(targetId=task.id){const target=workspace.tasks.find(t=>t.id===targetId);if(!target)return;if(target.id!==task.id)chooseTask(target.id);setFileId(target.files[0]?.id||null);setModal('files')}
 function chooseTask(id:string){if(viewStage==='applying')return;operation.current?.abort();setViewStage(null);setWorkspace(s=>switchTask(s,id));setSidebar(false);setHistory(null);setModal(null);notify('Task opened. Confirm its hardware to continue.')}
 function saveLeave(){operation.current?.abort();setSidebar(true);if(mode==='local'){void flush().then(()=>notify('Workspace saved in the local database.')).catch(()=>{});return}if(waiting)go(stage==='applying'?'review':'request');notify('Progress saved on this device.')}
 async function cancelDiagnosis(next:Stage='request'){if(!diagnosis)return;try{await localApi(`/api/jobs/${encodeURIComponent(diagnosis.id)}/cancel`,{});await reload();setDiagnosis(null);setWorkspace(s=>setStage(s,next));notify(`${agentName} task cancelled.`)}catch(e){setError((e as Error).message)}}
 async function investigate(){if(round.applied){go('feedback');return}if(!obs.issues.length)return;setError('');
 if(mode==='local'){if(!agentStatus?.authenticated){setModal('agent');setError(`Connect ${agentName} before starting a diagnosis.`);return}try{await flush();const job=await localApi<JobView>('/api/agent/investigate',{taskId:task.id,roundId:round.id,model:model||undefined,provider});await reload();setDiagnosis(job)}catch(e){setError((e as Error).message);providerChanged(e)}return}
 if(mode!=='demo'){setError('The local service is unavailable. Reload after starting it.');return}
 const ctl=new AbortController();operation.current?.abort();operation.current=ctl;setProgress({progress:0,message:'Opening the demo context folder'});setWorkspace(s=>setStage(s,'investigating'));try{const result=await agent.investigate({task,round},{signal:ctl.signal,onProgress:setProgress});if(!ctl.signal.aborted)setWorkspace(s=>setStage(updateRound(s,{suggestion:result,applied:false}),'review'))}catch(e){if((e as Error).name!=='AbortError'){setError((e as Error).message);go('request')}}}
 async function apply(){if(round.applied){go('test');return}setError('');if(mode==='local'){if(suggestion?.version!==2||suggestion.outcome!=='proposal'){setError('Run a new diagnosis to create a reviewable proposal.');return}if(applyKey.current?.suggestionId!==suggestion.id)applyKey.current={suggestionId:suggestion.id,key:crypto.randomUUID()};setViewStage('applying');setProgress({progress:35,message:'Checking source hashes and saving a reversible backup…'});try{const result=await runMutation(()=>localApi<ApplyResponse>('/api/agent/apply',{taskId:task.id,roundId:round.id,suggestionId:suggestion.id,idempotencyKey:applyKey.current!.key}));applyKey.current=null;notify(`Applied ${result.changedFiles.length} file change(s). No hardware was run.`)}catch(e){setError((e as Error).message)}finally{setViewStage(null)}return}if(mode!=='demo')return;operation.current?.abort();const ctl=new AbortController();operation.current=ctl;setProgress({progress:0,message:'Preparing a local checkpoint'});setWorkspace(s=>setStage(s,'applying'));
 try{await agent.applySuggestion({task,round},{signal:ctl.signal,onProgress:setProgress});if(!ctl.signal.aborted)setWorkspace(s=>setStage(applyRoundChange(s),'test'))}catch(e){if((e as Error).name!=='AbortError'){setError((e as Error).message);go('review')}}}
 function simulate(next:Stage){setPlaying(true);notify('Playing an illustrative animation. Your code and hardware are not running.');if(runTimer.current)clearTimeout(runTimer.current);runTimer.current=setTimeout(()=>{setPlaying(false);go(next)},stage==='test'?9000:7200)}
 function preview(){setPlaying(p=>!p)}
 function complete(){if(!feedback)return;const submittedRoundId=round.id;setWorkspace(s=>getActiveRound(s).id===submittedRoundId&&!getActiveRound(s).completedAt&&getActiveRound(s).applied?completeRound(s,feedback,note):s);setFeedback(null);setNote('');notify(`Round ${round.number} saved. Ready for your next observation.`)}
 async function undo(){if(!suggestion)return;if(mode==='local'){if(!round.operationId){setError('This legacy round has no backend backup. Its historical change cannot be undone automatically.');return}setViewStage('applying');setProgress({progress:35,message:'Checking current files before restoring the backup…'});try{await runMutation(()=>localApi<ApplyResponse>(`/api/operations/${encodeURIComponent(round.operationId!)}/undo`,{idempotencyKey:`undo-${round.operationId}`}));notify('Original files restored from the local backup.')}catch(e){setError((e as Error).message)}finally{setViewStage(null)}return}setWorkspace(s=>{const t=getActiveTask(s);return setStage(updateRound(updateTask(s,{files:t.files.map(f=>f.name===suggestion.fileName?{...f,content:f.content.replace(suggestion.codeAfter,suggestion.codeBefore),size:new TextEncoder().encode(f.content.replace(suggestion.codeAfter,suggestion.codeBefore)).length,updatedAt:new Date().toISOString()}:f)}),{applied:false}),'review')});notify('Demo parameter restored to its previous value.')}
 async function importFiles(list:FileList|null){if(!list)return;const targetTaskId=task.id;const files:ProjectFile[]=[];for(const f of Array.from(list)){if(task.files.some(existing=>existing.linked&&(existing.relativePath||existing.name)===f.name)){notify(`${f.name} is already linked. Remove it from this task before importing a copy with the same path.`);continue}if(f.size>1024*1024){notify(`${f.name} exceeds the 1 MB text-file limit.`);continue}if(!/\.(py|js|ts|tsx|jsx|ino|cpp|h|c|json|log|csv|txt|md)$/i.test(f.name)){notify('Import code, JSON, logs, CSV, or text files.');continue}try{files.push(makeFile(f.name,await readUtf8File(f),inferFileKind(f.name)))}catch(e){notify(`${f.name}: ${(e as Error).message}`)}}if(files.length){setWorkspace(s=>upsertFiles(s,files,targetTaskId));setFileId(task.files.find(f=>f.name===files[0].name)?.id||files[0].id);notify(`${files.length} file${files.length>1?'s':''} imported. Matching filenames are replaced.`)}if(upload.current)upload.current.value=''}
 function useExamples(){const example=createExampleWorkspace().tasks[0].files;setWorkspace(s=>updateTask(s,{files:example.map(f=>makeFile(f.name,f.content,f.kind,'sample'))}));notify('Example hardware, code and run log added.')}
 function signIn(e:React.FormEvent){e.preventDefault();const p={name:authName.trim()||email.split('@')[0]||'Maker',email};const saved=persistProfile(p);setProfile(p);setPassword('');setScreen('app');notify(saved?'Demo workspace opened. Your work stays on this device.':'Demo workspace opened. Browser storage is unavailable; export your work before leaving.')}
 function signOut(){operation.current?.abort();setWorkspace(s=>s.stage==='applying'?setStage(s,'review'):s.stage==='investigating'?setStage(s,'request'):s);const saved=persistProfile(null);setProfile(null);setPassword('');setScreen('landing');setChatOpen(false);setAccountOpen(false);setModal(null);setSidebar(false);if(!saved)notify('Signed out here. This browser could not clear its saved demo profile.')}
 async function chat(){if(!chatInput.trim()||chatJob?.status==='running')return;const q=chatInput.trim();setChatInput('');if(mode==='local'){if(!agentStatus?.authenticated){setChatInput(q);setModal('agent');return}try{await flush();const job=await localApi<JobView>('/api/agent/chat',{taskId:task.id,message:q,model:model||undefined,provider});await reload();setMessages(await localApi<ChatMessage[]>(`/api/tasks/${encodeURIComponent(task.id)}/messages`));setChatJob(job)}catch(e){setError((e as Error).message);setChatInput(q);providerChanged(e)}return}if(mode!=='demo')return;let text=`Demo: for ${task.name}, I have ${task.files.length} files and ${task.rounds.filter(r=>r.completedAt).length} previous rounds.`;if(/why|change|explain/i.test(q)&&suggestion)text=`Demo: ${suggestion.rationale}`;else if(/file|code/i.test(q))text=`Demo files: ${task.files.map(f=>f.name).join(', ')||'none'}.`;else if(/safe|run|hardware/i.test(q))text='The animation is illustrative. This demo never runs code or physical hardware.';const stamp=new Date().toISOString();setMessages(m=>[...m,{id:crypto.randomUUID(),role:'you',text:q,createdAt:stamp},{id:crypto.randomUUID(),role:'bit',text,createdAt:stamp}])}
 async function connectCodex(){setConnecting(true);setError('');try{const result=await localApi<{authUrl:string;loginId?:string}>('/api/codex/login',{});setAuthUrl(result.authUrl);if(result.authUrl)window.open(result.authUrl,'_blank','noopener,noreferrer')}catch(e){setError((e as Error).message)}finally{setConnecting(false)}}
 /** Another window switched providers: show the current one instead of sending to it. */
