 async function claudeSettings(path:string,method:'PUT'|'DELETE',body?:unknown){setProviderBusy(true);setError('');try{setStatus(await localApi<ServiceStatus>(path,body,{method}));return true}catch(e){setError((e as Error).message);return false}finally{setProviderBusy(false)}}
